create table public.operator_queue_observation_snapshots (kind text primary key check (kind in ('waiting','running','retryable_failure','dead_letter')), state text not null check (state in ('healthy','degraded','error','empty','unknown')), observed_at timestamptz, safe_code text check (safe_code is null or safe_code ~ '^[A-Z][A-Z0-9_]{0,63}$'), metric_value integer check (metric_value is null or metric_value >= 0), fact_kind text not null default 'unknown' check (fact_kind in ('observed','inference','unknown')), updated_at timestamptz not null default statement_timestamp());
create table public.operator_release_observation_snapshots (id boolean primary key default true check (id = true), version_code text, commit_sha_prefix text check (commit_sha_prefix is null or commit_sha_prefix ~ '^[a-f0-9]{0,12}$'), deployed_at timestamptz, rollback_candidate_code text check (rollback_candidate_code is null or rollback_candidate_code ~ '^[A-Z][A-Z0-9_]{0,63}$'), verification_state text not null default 'unknown' check (verification_state in ('verified','failed','pending','unknown')), observed_at timestamptz, fact_kind text not null default 'unknown' check (fact_kind in ('observed','inference','unknown')), updated_at timestamptz not null default statement_timestamp());
alter table public.operator_queue_observation_snapshots enable row level security; alter table public.operator_release_observation_snapshots enable row level security;
revoke all on public.operator_queue_observation_snapshots, public.operator_release_observation_snapshots from public, anon, authenticated; grant select, insert, update on public.operator_queue_observation_snapshots, public.operator_release_observation_snapshots to service_role;
create or replace function public.get_operator_system_observations_v2() returns jsonb language plpgsql security definer set search_path = '' stable as $$
declare base jsonb; queue jsonb; release jsonb;
begin
  base := public.get_operator_system_observations();
  with queue_rows as (
    select 'waiting'::text kind, count(*)::integer count, max(job.queued_at) observed_at, null::text safe_code from public.conversation_jobs job where job.queued_at >= statement_timestamp() - interval '24 hours' and job.status = 'queued'
    union all select 'running', count(*)::integer, max(coalesce(job.started_at, job.heartbeat_at)), null from public.conversation_jobs job where job.queued_at >= statement_timestamp() - interval '24 hours' and job.status in ('running', 'cancel_requested')
    union all select 'retryable_failure', count(*)::integer, max(coalesce(job.dispatch_failed_at, job.completed_at, job.heartbeat_at)), 'NEEDS_ATTENTION' from public.conversation_jobs job where job.queued_at >= statement_timestamp() - interval '24 hours' and (job.status = 'needs_attention' or job.dispatch_failed_at is not null)
    union all select 'dead_letter', count(*)::integer, max(coalesce(event.processed_at, event.received_at)), 'DEAD_LETTER' from public.provider_webhook_events event where event.received_at >= statement_timestamp() - interval '24 hours' and event.status = 'dead_letter'
  ) select jsonb_agg(jsonb_build_object('kind', kind, 'count', count, 'state', case when count = 0 then 'empty' else case when kind = 'dead_letter' then 'error' when kind = 'retryable_failure' then 'degraded' else 'healthy' end end, 'freshness', case when observed_at is null then 'empty' when observed_at < statement_timestamp() - interval '1 day' then 'stale' else 'fresh' end, 'observed_at', observed_at, 'safe_code', case when count = 0 then null else safe_code end, 'fact_kind', 'observed') order by kind) into queue from queue_rows;
  select jsonb_build_object('version_code', version_code, 'commit_sha_prefix', commit_sha_prefix, 'deployed_at', deployed_at, 'rollback_candidate_code', rollback_candidate_code, 'verification_state', verification_state, 'source', 'release', 'fact_kind', fact_kind, 'freshness', case when observed_at is null then 'unknown' when observed_at < statement_timestamp() - interval '1 day' then 'stale' else 'fresh' end) into release from public.operator_release_observation_snapshots where id = true;
  return jsonb_build_object('items', (select jsonb_agg(item || jsonb_build_object('fact_kind', case when item->>'source' in ('conversation_jobs','provider_webhooks','operation_events') then 'observed' else 'unknown' end)) from jsonb_array_elements(base->'items') item), 'observation_window', '24h', 'queue', queue, 'release', coalesce(release, jsonb_build_object('version_code', null, 'commit_sha_prefix', null, 'deployed_at', null, 'rollback_candidate_code', null, 'verification_state', 'unknown', 'source', 'release', 'fact_kind', 'unknown', 'freshness', 'unknown')));
end; $$;
revoke all on function public.get_operator_system_observations_v2() from public, anon, service_role; grant execute on function public.get_operator_system_observations_v2() to authenticated;
